; code
L5B8C:
  LD HL,$E9F6             ; HL=$E9F6
  LD DE,$FFFF             ; DE=$FFFF
L5B8C_0:
  PUSH HL                 ; Push HL onto the stack
  LD BC,$5FB3             ; BC=$5FB3
  OR A                    ; Clear the carry flag and set the zero flag if A=0
  SBC HL,BC               ; HL=HL-carry-BC
  POP HL                  ; Pop last item from stack into HL
  RET Z                   ; Return if the zero flag is set
  LD A,(HL)               ; A=PEEK HL
  CP $97                  ; Set the zero flag if A=$97, or the carry flag if
                          ; A<$97
  JR Z,L5B8C_1            ; Jump to L5B8C_1 if A=$97
  LDD                     ; POKE DE,PEEK HL; HL=HL-1; DE=DE-1; BC=BC-1
  JR L5B8C_0              ; Jump to L5B8C_0
L5B8C_1:
  DEC HL                  ; HL=HL-1
  LD B,(HL)               ; B=PEEK HL
  BIT 7,B                 ; Set the zero flag if bit 7 of B is 0
  JR Z,L5B8C_2            ; Jump to L5B8C_2 if bit 7 of B is reset
  RES 7,B                 ; Reset bit 7 of B
  LD A,B                  ; A=B
  AND A                   ; Clear the carry flag and set the zero flag if A=0
  JR Z,L5B8C_3            ; Jump to L5B8C_3 if A=0
  CP $03                  ; Set the zero flag if A=$03, or the carry flag if
                          ; A<$03
  LD A,$00                ; A=$00
  JR NC,L5B8C_3           ; Jump to L5B8C_3 if the carry flag is not set
  LD A,$97                ; A=$97
  JR L5B8C_3              ; Jump to L5B8C_3
L5B8C_2:
  DEC HL                  ; HL=HL-1
  LD A,(HL)               ; A=PEEK HL
L5B8C_3:
  LD (DE),A               ; POKE DE,A
  DEC DE                  ; DE=DE-1
  DJNZ L5B8C_3            ; Decrement B and jump to L5B8C_3 if B>0
  DEC HL                  ; HL=HL-1
  JR L5B8C_0              ; Jump to L5B8C_0

