; code
L8000:
  DI                      ; Disable interrupts
  LD C,$00                ; C=$00
  EXX                     ; Exchange BC, DE and HL with BC', DE' and HL'
  POP HL                  ; Pop last item from stack into HL
  PUSH HL                 ; Push HL onto the stack
  DEC HL                  ; HL=HL-1
  LD D,(HL)               ; D=PEEK HL
  DEC HL                  ; HL=HL-1
  LD E,(HL)               ; E=PEEK HL
  LD HL,$003A             ; HL=$003A
  ADD HL,DE               ; HL=HL+DE
  PUSH HL                 ; Push HL onto the stack
  LD BC,$058C             ; BC=$058C
  LD DE,L8000_2           ; DE=$803A
L8000_0:
  LD A,(DE)               ; A=PEEK DE
  EX AF,AF'               ; Exchange AF and AF'
  LD A,(HL)               ; A=PEEK HL
  LD (DE),A               ; POKE DE,A
  EX AF,AF'               ; Exchange AF and AF'
  LD (HL),A               ; POKE HL,A
  INC HL                  ; HL=HL+1
  INC DE                  ; DE=DE+1
  DEC BC                  ; BC=BC-1
  LD A,B                  ; A=B
  OR C                    ; A=A|C
  JR NZ,L8000_0           ; Jump to L8000_0 if A>0
  CALL L8000_2            ; CALL L8000_2
  POP HL                  ; Pop last item from stack into HL
  LD DE,L8000_2           ; DE=$803A
  LD BC,$058C             ; BC=$058C
L8000_1:
  LD A,(DE)               ; A=PEEK DE
  EX AF,AF'               ; Exchange AF and AF'
  LD A,(HL)               ; A=PEEK HL
  LD (DE),A               ; POKE DE,A
  EX AF,AF'               ; Exchange AF and AF'
  LD (HL),A               ; POKE HL,A
  INC HL                  ; HL=HL+1
  INC DE                  ; DE=DE+1
  DEC BC                  ; BC=BC-1
  LD A,B                  ; A=B
  OR C                    ; A=A|C
  JR NZ,L8000_1           ; Jump to L8000_1 if A>0
  RET                     ; Return
L8000_2:
  LD ($8364),SP           ; POKE $8364,SP-lo; POKE $8365,SP-hi
  LD SP,$83F7             ; SP=$83F7
  LD A,I                  ; A=I
  LD H,A                  ; H=A
  LD L,$00                ; L=$00
  LD D,(HL)               ; D=PEEK HL
  LD E,D                  ; E=D
  EX DE,HL                ; Exchange DE and HL
  LD ($83F7),HL           ; POKE $83F7,L; POKE $83F8,H
  LD DE,$83F9             ; DE=$83F9
  LD BC,$0003             ; BC=$0003
  LDIR                    ; POKE DE,PEEK HL; HL=HL+1; DE=DE+1; BC=BC-1; repeat
                          ; until BC=0
  LD DE,$8340             ; DE=$8340
  DEC HL                  ; HL=HL-1
  LD (HL),D               ; POKE HL,D
  DEC HL                  ; HL=HL-1
  LD (HL),E               ; POKE HL,E
  DEC HL                  ; HL=HL-1
  LD (HL),$C3             ; POKE HL,$C3
  LD B,$09                ; B=$09
  LD HL,$8422             ; HL=$8422
L8000_3:
  LD E,(HL)               ; E=PEEK HL
  INC HL                  ; HL=HL+1
  LD D,(HL)               ; D=PEEK HL
  INC HL                  ; HL=HL+1
  LD A,(HL)               ; A=PEEK HL
  INC HL                  ; HL=HL+1
  LD (DE),A               ; POKE DE,A
  DJNZ L8000_3            ; Decrement B and jump to L8000_3 if B>0
  EI                      ; Enable interrupts
  HALT                    ; Wait for the next interrupt
  EXX                     ; Exchange BC, DE and HL with BC', DE' and HL'
  LD HL,$843D             ; HL=$843D
  LD B,$00                ; B=$00
  SLA C                   ; Shift C left (copying bit 7 into the carry flag,
                          ; and resetting bit 0)
  ADD HL,BC               ; HL=HL+BC
  LD E,(HL)               ; E=PEEK HL
  INC HL                  ; HL=HL+1
  LD D,(HL)               ; D=PEEK HL
  EX DE,HL                ; Exchange DE and HL
  LD C,B                  ; C=B
  JP L8109_0              ; Jump to L8109_0
; This entry point is used by the routine at L8323.
L8000_4:
  LD A,C                  ; A=C
  AND A                   ; Clear the carry flag and set the zero flag if A=0
  JP NZ,L8243             ; Jump to L8243 if A>0
; This entry point is used by the routine at L813C.
L8000_5:
  LD C,$05                ; C=$05
  EXX                     ; Exchange BC, DE and HL with BC', DE' and HL'
  EX DE,HL                ; Exchange DE and HL
